function tsHtml(){return head("ts",REALB,"Planlı tapşırıqlar vaxtı çatanda sinif kompüterlərinə həqiqətən əmr göndərir. Panel səhifəsi açıq olmalıdır (brauzer sekması). Tətil günlərində işləmir.")+`<section class="pn"><h3>Yeni tapşırıq</h3><div class="row"><input class="in" id="ts-n" placeholder="Ad (məs. Səhər kilidi)" maxlength="40"><input class="in" type="time" id="ts-t" value="08:00" style="max-width:130px"><select class="in" id="ts-a" style="flex:none">${Object.entries(TSA).map(([k,v])=>`<option value="${k}">${v}</option>`).join("")}</select></div><div class="row" style="margin-top:10px"><input class="in" id="ts-x" placeholder="Mesaj mətni (yalnız “mesaj yay” üçün)" maxlength="120"></div><div class="row" style="margin-top:10px">${[1,2,3,4,5,6,7].map(d=>`<button class="bt ${WC.tsd.includes(d)?"pr":""}" data-a="tsday" data-k="${d}">${DAYLABEL[d]}</button>`).join("")}<span class="sp"></span><button class="bt pr" data-a="tsadd">Əlavə et</button></div></section><section class="pn"><h3>Tapşırıqlar</h3>${WS.sched.map(t=>`<div class="li" style="flex-wrap:wrap"><button class="tg ${t.on?"on":""}" data-a="tstog" data-k="${t.id}"></button><span class="sp"><b>${esc(t.n)}</b><div class="mu">${t.t} · ${t.d.map(d=>DAYLABEL[d]).join(", ")||"gün yoxdur"} · ${TSA[t.a]}${t.x?" — “"+esc(t.x)+"”":""} · növbəti: ${tsNext(t)}${t.last?" · son: "+esc(t.last):""}</div></span><button class="bt" data-a="tsrun" data-k="${t.id}">İndi işlət</button><button class="ib2" data-a="tsdel" data-k="${t.id}" aria-label="Sil">${I("trash")}</button></div>`).join("")||'<p class="mu">Planlı tapşırıq yoxdur.</p>'}</section>`}
function tsRun(t,manual){const x=t.a==="message"?{text:t.x||"Diqqət!"}:{};cmd("all",t.a,x,null);t.last=(manual?"əl ilə ":"")+hmm(Date.now());wsave();addEv("Information","TaskScheduler",`“${t.n}” işlədi: ${TSA[t.a]}`);notify(`Planlı tapşırıq: ${t.n}`,{k:"task"});toast(`“${t.n}” göndərildi`)}
function tsTick(){if(!S||!WS.sched.length)return;const n=sdate(),key=ymd(n)+" "+pad(n.getHours())+":"+pad(n.getMinutes()),day=((n.getDay()+6)%7)+1;if(holOf(n).some(h=>h.kind!=="special"))return;let ch=0;for(const t of WS.sched)if(t.on&&t.t===pad(n.getHours())+":"+pad(n.getMinutes())&&t.d.includes(day)&&t.key!==key){t.key=key;tsRun(t,false);ch=1}if(ch)wsave()}
